function mb.weatherStrength(jE)
local kE=mb.fx(jE)
local lE=kE.dmg/kE.cd/kE.hp/kE.speed*(1+(kE.range-1)/2)
for mE,nE in pairs(kE.kinds)do
lE=lE*(1+bb.rogueShare(mE)*nE)
end
if kE.ice>0 then
local oE=bb.rogueShare(qAe[2289])
lE=lE*(oE+(1-oE)/(1-kE.ice+kE.ice/gb.modFactor(qAe[2697])))
end
if kE.fly>0 then
lE=lE*(1-kE.fly*0.5)
end
if kE.noCC then
lE=lE*0.95
end
if kE.shroud then
lE=lE*0.9
end
if kE.zap then
lE=lE*0.85
end
return lE/mb.weatherK(jE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(pE)
local qE=pE and type(P.hunt)==qAe[2149]and type(P.hunt.wk)==qAe[2149]and P.hunt.wk[tostring(pE)]or nil
