function mb.weatherLearn()
if bb.withOthers or#game:GetService(qAe[1047]):GetPlayers()>1 then
return
end
local rE=bb.huntWeather or mb.weatherNow()
local sE,tE=bb.pred,bb.calRun
if not rE or type(sE)~=qAe[2149]or type(tE)~=qAe[2149]then
return
end
local function uE(vE,wE)
return type(vE)==qAe[2149]and tonumber(vE[wE]or vE[tostring(wE)])or nil
end
local xE={}
for yE=2,bb.wave()do
local zE,AE=uE(tE.alive,yE),uE(sE.aliveAt,yE)
if zE and AE and zE>0 and AE>0 then
table.insert(xE,zE/AE)
end
end
if#xE<3 then
return
end
table.sort(xE)
local BE=xE[math.ceil(#xE/2)]
P.hunt.wk=type(P.hunt.wk)==qAe[2149]and P.hunt.wk or{}
