GE=U.clamp(GE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(rE),old=CE}
P.hunt.wk[tostring(rE)]={k=GE,n=(type(CE)==qAe[2149]and tonumber(CE.n)or 0)+1,at=os.time()}
F.log(1,qAe[2698],string.format(qAe[2699],tostring(rE),BE,tostring(rE),GE,EE,P.hunt.wk[tostring(rE)].n))
end
function mb.cardGems(HE,IE)
