local VF=gb.realShares(nF.key,5)
local function WF(XF)
local YF,ZF={},0
pcall(gb.run,nF,gb.teamFrom(XF,nF.map),{hpMul=1,dealt=YF})
task.wait()
for _F,aG in pairs(YF)do
ZF=ZF+(tonumber(aG)or 0)
end
local bG={}
for cG,dG in ipairs(XF)do
bG[dG.unit_id]=tonumber(VF[dG.unit_id])or(((tonumber(YF[V.name(dG.unit_id)])or 0)+(tonumber(YF[qAe[2724]..tostring(dG.unit_id)])or 0))/math.max(1,ZF))
