if mb.teamDrop(SF,uF)>=1 or U.now()-qF>pF then
break
end
local gG=false
for hG,iG in ipairs(NF)do
if U.now()-qF>pF then
break
end
local jG=false
for kG,lG in ipairs(SF)do
if lG.uuid==iG.u.uuid or V.sameGroup(lG.unit_id,iG.u.unit_id)then
jG=true
break
end
end
if not jG then
local mG={}
for nG,oG in ipairs(SF)do
if(mb.unitDrop(oG,uF))<iG.d then
table.insert(mG,{i=nG,sc=(tonumber(eG[oG.unit_id])or 0)+((V.isFarm(oG.unit_id)or V.allyBuff(oG.unit_id))and 1e300 or 0)})
end
end
table.sort(mG,function(pG,qG)
return pG.sc<qG.sc
end)
for rG=1,math.min(2,#mG)do
local sG=table.clone(SF)
local tG=sG[mG[rG].i]
sG[mG[rG].i]=iG.u
if mb.teamDrop(sG,uF)>mb.teamDrop(SF,uF)+1e-6 and vF(sG,CF)then
table.insert(TF,string.format(qAe[2725],V.name(iG.u.unit_id),V.name(tG.unit_id)))
SF,gG=sG,true
eG=WF(SF)
break
end
end
end
if gG then
break
end
end
if not gG then
break
end
end
if#TF==0 then
