function kb.xpGuess(xdb)
local ydb=xdb.level and N.Levels[xdb.level]
if not ydb then
return 0
end
local zdb=math.min(9,tonumber(ydb.story_world_rank)or tonumber(xdb.rank)or 9)
local Adb=tonumber(ydb.story_level_rank)or 6
local Bdb=(xdb.kind==qAe[2195]and 1.5 or 1)*(zdb>5 and 2 or 1)
local Cdb=2.1564^(zdb-1)*(40+10*Adb)/Bdb
if xdb.kind==qAe[2174]then
Cdb=3*30*2.1564^(zdb-1)/Bdb
end
local Ddb=zdb>=9 and 0.3 or(zdb>=7 and 0.5 or 1)
return Cdb*Ddb*6
end
