for Zdb,_db in ipairs(kb.foodHeld())do
local aeb=_db.xp*Udb
local beb=math.min(_db.n,math.floor((Vdb-Xdb)/math.max(1,aeb)))
if beb>0 then
Wdb[_db.id]=beb
Xdb=Xdb+beb*aeb
Ydb=Ydb+beb
end
end
return{feed=Wdb,planned=Xdb,n=Ydb}
