cb.add(string.format(qAe[3207],ieb,ceb.name),ieb,qAe[3208],string.format(qAe[3209],U.fmt(peb),reb))
kb.note(string.format(qAe[3210],ceb.name,ieb,U.fmt(peb),reb,math.abs(peb-heb)>heb*0.1 and string.format(qAe[3211],U.fmt(heb))or qAe[1068]))
