function eb.upgradeGain(oGb,pGb,qGb,rGb,sGb,tGb)
local uGb,vGb=pGb[qGb],pGb[qGb+1]
local wGb=(uGb.cd>0 and uGb.damage/uGb.cd or 0)
local xGb=(vGb.cd>0 and vGb.damage/vGb.cd or 0)*V.aoe(vGb.atk,vGb.range)/math.max(0.3,V.aoe(uGb.atk,uGb.range))
local yGb=wGb>0 and oGb*(xGb/wGb-1)or(tGb or 0)
local zGb=pGb[qGb+2]
if zGb and qGb+1<pGb.max and zGb.cd>0 and vGb.cd>0 and wGb>0 then
local AGb=oGb*((zGb.damage/zGb.cd)/wGb-1)
local BGb=rGb+zGb.cost*sGb
if AGb/BGb>yGb/rGb then
yGb=yGb+(AGb/BGb*rGb-yGb)*0.5
end
end
local CGb=(vGb.range or 0)>(uGb.range or 0)and(1+((vGb.range-uGb.range)/math.max(1,uGb.range)))or 1
return math.max(0,yGb)*CGb
end
function eb.dpsFor(DGb,EGb)
if EGb<=0 then
return 0
end
local FGb={}
for GGb,HGb in ipairs(DGb)do
if not HGb.farm and not HGb.grif and HGb.gain>0 then
table.insert(FGb,HGb)
end
end
table.sort(FGb,function(IGb,JGb)
return IGb.gain/IGb.cost>JGb.gain/JGb.cost
end)
local KGb,LGb=0,0
for MGb,NGb in ipairs(FGb)do
if EGb<=0 then
break
end
LGb=NGb.gain/NGb.cost
local OGb=math.min(1,EGb/NGb.cost)
KGb=KGb+NGb.gain*OGb
EGb=EGb-NGb.cost*OGb
end
return KGb+math.max(0,EGb)*LGb*0.7
end
function eb.shieldDps(PGb,QGb,RGb,SGb,TGb,UGb,VGb)
if(SGb or 0)<=0 or(PGb or 0)<=0 or(TGb or 0)<=0 then
return PGb or 0
end
QGb,RGb,UGb=math.max(0.3,QGb or 2),math.max(1,RGb or 1),UGb or 1
local WGb=PGb*UGb*QGb/RGb
return TGb*RGb/((SGb/math.max(1,VGb or 1)+math.max(1,TGb/WGb))*QGb)/UGb
end
function eb.shieldGain(XGb,YGb,ZGb,_Gb,aHb,bHb,cHb,dHb)
local eHb,fHb=V.attackInfo(YGb.atk,YGb.range),V.attackInfo(_Gb.atk,_Gb.range)
local gHb=eb.shieldDps(XGb,(tonumber(YGb.cd)or 2)*(cHb or 1),eHb.n,aHb,bHb,dHb,eHb.hits)
local hHb=eb.shieldDps(ZGb,(tonumber(_Gb.cd)or 2)*(cHb or 1),fHb.n,aHb,bHb,dHb,fHb.hits)
local iHb=math.max(0,((tonumber(_Gb.range)or 0)-(tonumber(YGb.range)or 0))/math.max(1,tonumber(YGb.range)or 1))
return math.max(0,hHb-gHb)+gHb*iHb
end
function eb.shieldWork(jHb,kHb,lHb,mHb,nHb,oHb,pHb,qHb,rHb)
if(mHb or 0)<=0 then
return 0
end
local sHb=3*mHb*(nHb or 1)/math.max(1,oHb or 20)
if(lHb or 0)>=sHb then
return 0
end
return math.max(1,jHb or 1)*math.max(1,rHb or 1)/math.max(0.3,kHb or 2)*math.min(pHb or 0,qHb or 0)
end
function eb.holdGain(tHb,uHb,vHb,wHb)
if not tHb or(uHb or 0)<=0 then
return 0
end
local xHb,yHb=tonumber(tHb.stun)or 0,tonumber(tHb.slowTime)or 0
if xHb<=0 and yHb<=0 then
return 0
end
local zHb,AHb=xHb>0 and xHb or yHb,xHb>0 and 1 or(tonumber(tHb.slowPct)or 0.3)
local BHb=AHb*zHb/(zHb+(tonumber(tHb.ccCd)or 8))
local CHb=BHb/math.max(0.1,1-BHb)
return uHb*CHb*U.clamp(vHb or 0.5,0,1)*math.min(1,(tonumber(tHb.n)or 1)/2)/(1+(wHb or 0))
end
function eb.bleedGain(DHb,EHb,FHb,GHb)
if(DHb or 0)<=0 then
return 0
end
local HHb=EHb or 0
for IHb,JHb in ipairs(FHb or{})do
HHb=math.max(HHb,(tonumber(JHb.hp)or 0)*0.5)
end
return DHb*HHb*(GHb and 0.5 or 1)
end
function eb.bleedShare(KHb,LHb,MHb,NHb)
if KHb<=0 or not LHb then
return 0
end
if NHb then
return LHb==0 and KHb or KHb/(LHb+1)
end
return MHb<LHb and KHb/(LHb-MHb)or 0
end
function eb.keepsUp(OHb,PHb,QHb,RHb,SHb)
local THb=OHb.coming
if not(THb and#THb>0 and OHb.waveSec)then
return true
end
local UHb=OHb.eff or 1
local VHb=OHb.money-QHb
local WHb=(OHb.teamDps or 0)*(OHb.shieldK or 1)+(RHb or 0)*UHb+eb.dpsFor(PHb,math.max(0,VHb))*UHb
local XHb=(OHb.farmNow or 0)+(SHb or 0)
local YHb=(OHb.roadSec or 130)*U.clamp(OHb.cover or 0.6,0.1,1)
local ZHb=OHb.hpAlive or 0
for _Hb,aIb in ipairs(THb)do
ZHb=math.max(0,ZHb+aIb.hp-WHb*OHb.waveSec)
local bIb=WHb*YHb
if ZHb>bIb then
return false,_Hb,bIb/math.max(1,ZHb)
end
if _Hb< #THb then
WHb=WHb+eb.dpsFor(PHb,(aIb.reward or 0)+XHb)*UHb*(0.85^_Hb)
end
end
return true
end
function eb.decide(cIb,dIb)
local eIb=U.clamp(dIb.cover or 0.6,0.1,1)
local fIb=math.max(O.clearSec,0.7*(dIb.roadSec or 50)*eIb)
local gIb=(dIb.clearSec or 0)>fIb
dIb.piling=dIb.piling and gIb
local hIb=dIb.attackers>0 and dIb.pressure<math.min(O.safeReach,eIb*0.75)and not dIb.piling and not gIb
local iIb=dIb.pressure>=math.min(O.dangerReach,eIb*0.9)or(dIb.piling and dIb.enemies>=18)
local jIb,kIb
for lIb,mIb in ipairs(cIb)do
if mIb.farm then
if O.farmUnits and mIb.gain>0 then
mIb.payback=mIb.cost/mIb.gain
if dIb.left-1>=mIb.payback+(dIb.farmSpare or O.farmSpare)and(not jIb or mIb.payback<jIb.payback)then
jIb=mIb
end
end
else
mIb.ratio=mIb.gain/math.max(1,mIb.cost)
if not kIb or mIb.ratio>kIb.ratio then
kIb=mIb
end
end
end
if dIb.leak and dIb.attackers>0 then
local nIb
for oIb,pIb in ipairs(cIb)do
local qIb=not dIb.airLeak or(pIb.e and bb.cardAir(pIb.e.id))
if pIb.place and not pIb.farm and not pIb.idol and not pIb.grif and qIb and pIb.cost<=dIb.money and not(pIb.e and V.allyBuff(pIb.e.id))and(not nIb or pIb.gain>nIb.gain)then
nIb=pIb
end
end
if nIb then
return nIb,string.format(qAe[3875],math.floor(dIb.leak*100))
end
end
local rIb=dIb.future<dIb.wantLeft*1.1
local sIb,tIb,uIb=true,nil,nil
if jIb then
sIb,tIb,uIb=eb.keepsUp(dIb,cIb,jIb.cost,0,jIb.gain)
end
local vIb=dIb.coming and not eb.keepsUp(dIb,cIb,0,0,0)
local wIb=false
if bb.random and jIb and not iIb and dIb.attackers>=2 and jIb.payback<=dIb.left/3 then
local xIb=0
for yIb,zIb in ipairs(bb.mine or{})do
if V.isFarm(zIb._stats.id.Value)then
xIb=xIb+1
end
end
wIb=not jIb.place or xIb<4
end
if vIb and dIb.attackers>0 then
iIb=true
end
if iIb and kIb and kIb.grif then
