local loc,moc=pcall(jb.sim,doc,nil,true)
if loc and not joc(moc)then
return false,string.format(qAe[4160],foc,(hoc:gsub(qAe[3764],qAe[4161])),tostring(moc.margin or qAe[2390]))
end
end
if#eoc==0 then
return true
end
local noc
for ooc,poc in ipairs(eoc)do
local qoc,roc=pcall(jb.sim,poc,aoc,true)
if not qoc or joc(roc)then
return true
end
if not noc or(tonumber(roc.p)or 0)>(tonumber(noc.p)or 0)then
noc=roc
end
end
return false,string.format(qAe[4162],foc,hoc,tostring(noc and noc.margin or qAe[2390]))
end
