function jb.pick(Doc)
local Eoc,Foc=jb.curses(Doc),jb.lives(Doc)
local Goc=jb.res(Doc)
local Hoc=jb.rooms(Doc)
local Ioc={}
for Joc,Koc in ipairs(Hoc)do
table.insert(Ioc,tostring(Koc.r._r))
end
local Loc=table.concat(Ioc,qAe[3020])..string.format(qAe[4163],Foc,Goc,Eoc,W.teamSig())
if jb._pick and jb._pick.sig==Loc then
return jb._pick.x
end
local Moc,Noc,Ooc,Poc
for Qoc,Roc in ipairs(Hoc)do
local Soc=jb.roomValue(Roc,Goc)
local Toc,Uoc
for Voc,Woc in ipairs(jb.after(Doc,Roc.choice))do
local Xoc=jb.roomValue(Woc,Goc)
if not Toc or Xoc>Toc then
Toc,Uoc=Xoc,Woc
end
end
local Yoc,Zoc=jb.winP(Roc)
local _oc=Zoc~=nil and Zoc.won==false
local apc=Foc>=3 and 1 or(Foc==2 and 2 or 6)
local bpc=1-(1-Yoc)^math.max(1,Foc)
Roc.oldScore=bpc*(Soc+0.6*(Toc or 0))-(1-Yoc)*apc
if _oc then
Yoc=math.min(Yoc,jb.lossWin())
bpc=Yoc
apc=apc*2
end
Roc.p,Roc.sim,Roc.value,Roc.nextValue,Roc.nextRoom,Roc.simLost=Yoc,Zoc,Soc,Toc or 0,Uoc,_oc or nil
Roc.score=bpc*(Soc+0.6*(Toc or 0))-(1-Yoc)*apc
local cpc,dpc,epc=pcall(jb.curseGate,Roc,Doc)
if cpc and not dpc then
Roc.blocked=epc
end
if not Roc.blocked then
if not Moc or Roc.score>Moc.score then
Moc=Roc
end
if _oc then
if not Poc or Roc.score>Poc.score then
Poc=Roc
end
elseif not Ooc or Roc.score>Ooc.score then
Ooc=Roc
end
end
if not Noc or Roc.score>Noc.score then
Noc=Roc
end
end
if Moc and Moc.simLost and Ooc then
F.log(1,qAe[4164],string.format(qAe[4165],jb.roomName(Moc),tostring(Moc.sim and Moc.sim.margin or qAe[2390]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Ooc)))
elseif Moc and Poc and Poc~=Moc and Poc.oldScore>Moc.score then
F.log(1,qAe[4164],string.format(qAe[4166],jb.roomName(Poc),tostring(Poc.sim and Poc.sim.margin or qAe[2390]),jb.roomName(Moc)))
end
Moc=Moc or Noc
jb._pick={sig=Loc,x=Moc,rooms=Hoc}
return Moc
end
