jb.TOP_WORTH=0.08
function jb.shop(_pc,aqc)
local bqc=jb.cleared(_pc)
local cqc=jb.res(_pc)
local dqc=1+0.1*(jb.items(_pc)._curse_shop or 0)
local eqc=jb.shopAhead(_pc)and math.ceil(jb.LUCK_RESERVE*dqc)or 0
local fqc={}
local gqc,hqc={},0
for iqc,jqc in ipairs(jb.offers(aqc and aqc.data))do
jqc.cost=math.ceil(jqc.cost*dqc)
table.insert(gqc,tostring(jb.item(jqc.id).name or jqc.id))
if not jqc.bought and not jb.isCurse(jqc.id)then
jqc.luck=tonumber(jb.item(jqc.id).luck_increase)~=nil
jqc.v=jb.itemValue(jqc.id,_pc)
if not jqc.luck and jqc.v/math.max(1,jqc.cost)<jb.MIN_WORTH then
hqc=hqc+1
elseif jqc.v>0 and(jqc.luck or bqc>=10 or jqc.v/math.max(1,jqc.cost)>=jb.TOP_WORTH)then
table.insert(fqc,jqc)
end
end
end
table.sort(fqc,function(kqc,lqc)
if kqc.luck~=lqc.luck then
return kqc.luck
end
return kqc.v/math.max(1,kqc.cost)>lqc.v/math.max(1,lqc.cost)
end)
local mqc,nqc,oqc={},0,0
for pqc,qqc in ipairs(fqc)do
if qqc.cost<=cqc-(qqc.luck and 0 or eqc)then
if jb.buy(qqc)then
cqc=jb.res(jb.data())
table.insert(mqc,string.format(qAe[4176],tostring(jb.item(qqc.id).name or qqc.id),qqc.cost))
end
elseif qqc.cost<=cqc then
oqc=oqc+1
else
nqc=nqc+1
end
end
jb.note(string.format(qAe[4177],bqc,#gqc>0 and table.concat(gqc,qAe[2268])or qAe[4178],#mqc>0 and(qAe[4179]..table.concat(mqc,qAe[2268]))or(bqc<10 and qAe[4180]or(oqc>0 and qAe[4181]or qAe[4182])),cqc,nqc>0 and string.format(qAe[4183],nqc)or qAe[1068],oqc>0 and string.format(qAe[4184],oqc,eqc)or qAe[1068],hqc>0 and string.format(qAe[4185],hqc)or qAe[1068]))
