local trc=jb.walletDiff(drc,rrc)
F.log(1,qAe[4164],(qrc<hrc and qAe[4202]or qAe[4201])..trc)
P.dg.pay=P.dg.pay or{}
local urc={}
for vrc,wrc in pairs(rrc.items)do
