jb.note(string.format(qAe[4203],_qc,arc,Uqc and qAe[4204]or(Yqc<=1 and qAe[4205]or qAe[4206]),jb.luck(Tqc),(tonumber(N.cur(qAe[2219]))or 0)-crc))
local xrc,yrc,zrc=jb.res(jb.data())
if(Uqc or Zqc>=jb.ROOMS)and yrc+zrc>0 then
jb.note(string.format(qAe[4207],yrc,zrc))
W.rec(qAe[2877]).restUntil=os.time()+1800
return qAe[4208]
end
if not Uqc then
F.request(qAe[4186],qAe[4187])
end
