if not N.PC.is_valid_raycast_hit(TSc.Instance,SSc)then
return nil
end
local USc=TSc.Position
if bb.blockedSpot(USc)then
return nil
end
local VSc=(tonumber(SSc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(VSc*2,2.5,VSc*2)
bb.probe.CFrame=CFrame.new(USc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return USc
end
