for NVc,OVc in ipairs(bb.cands)do
local PVc,QVc,RVc=U.flat(OVc),0,0
for SVc,TVc in ipairs(AVc)do
if(U.flat(TVc.pos)-PVc).Magnitude<=LVc then
RVc=RVc+1
if math.abs(TVc.prog-KVc)<=0.05 then
