function bb.huntWeakText()
local Qgd=type(P.hunt)==qAe[2149]and P.hunt.runs or{}
if#Qgd<bb.HUNT_WEAK_RUNS then
return nil
end
local Rgd,Sgd,Tgd=0,0,{}
for Ugd=1,bb.HUNT_WEAK_RUNS do
local Vgd=Qgd[Ugd]
if type(Vgd)~=qAe[2149]or Vgd.won then
return nil
end
Rgd,Sgd=Rgd+(tonumber(Vgd.pearls)or 0),Sgd+(tonumber(Vgd.sec)or 0)
table.insert(Tgd,tonumber(Vgd.wave)or 0)
end
if Sgd<=0 then
return nil
end
table.sort(Tgd)
local Wgd=Tgd[math.ceil(#Tgd/2)]
local Xgd=Rgd/Sgd*60*(tonumber(O.pearlValue)or 0.35)
local Ygd={string.format(qAe[4708],bb.HUNT_WEAK_RUNS,Wgd,Xgd)}
local Zgd
for _gd,ahd in ipairs(W.lastScored or{})do
if ahd.kind~=qAe[2172]and(tonumber(ahd.score)or 0)>0 then
Zgd=ahd
break
end
end
if Zgd then
table.insert(Ygd,string.format(qAe[4709],tostring(Zgd.label),Zgd.score))
end
local bhd=0
for chd,dhd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[dhd]==false then
bhd=bhd+1
end
end
if W.onlyOn()then
table.insert(Ygd,qAe[4710])
elseif bhd>=4 then
table.insert(Ygd,string.format(qAe[4711],bhd))
end
table.insert(Ygd,qAe[4712])
return table.concat(Ygd,qAe[2530]),Xgd,Wgd
end
