function bb.pickRogue()
local fhd=bb.rogueOptions
if fhd and bb.hunt then
return bb.huntPick(fhd)
end
if not fhd then
local ghd=F.request(qAe[4687],qAe[3798],1)
return ghd
end
bb.fhP=bb.fhP or 1
local hhd=tonumber(P.fh.pmin)or 1
local ihd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local jhd,khd,lhd
for mhd,nhd in pairs(fhd)do
local ohd,phd=1,0
for qhd,rhd in pairs(type(nhd)==qAe[2149]and nhd.effects or{})do
if type(rhd)==qAe[2149]then
local shd,thd=bb.rogueEffect(rhd)
ohd=ohd*shd
phd=phd+thd
end
end
local uhd=math.log(math.max(0.05,ohd))*10
if phd>0 and bb.fhP*ohd>=hhd and not ihd then
uhd=uhd+100*phd
elseif phd>0 then
uhd=uhd-50+phd
end
if not khd or uhd>khd then
jhd,khd,lhd=mhd,uhd,ohd
end
end
bb.fhP=bb.fhP*(lhd or 1)
local vhd={}
for whd,xhd in pairs(fhd)do
local yhd={}
for zhd,Ahd in pairs(type(xhd)==qAe[2149]and xhd.effects or{})do
if type(Ahd)==qAe[2149]then
table.insert(yhd,bb.effectText(Ahd))
end
end
table.insert(vhd,tostring(whd)..qAe[4713]..table.concat(yhd,qAe[2790]))
end
bb.rogueOptions=nil
local Bhd=F.request(qAe[4687],qAe[3798],jhd)
F.log(1,qAe[4688],string.format(qAe[4714],bb.wave(),tostring(jhd),khd or 0,bb.fhP,hhd,table.concat(vhd,qAe[3977])))
return Bhd
end
function bb.rogueShare(Chd)
if not Chd then
return 0.5
end
local Dhd=tostring(Chd):gsub(qAe[4004],qAe[1068])
local Ehd,Fhd=0,0
for Ghd,Hhd in ipairs(bb.mine or{})do
local Ihd=Hhd._stats.id.Value
if not V.isFarm(Ihd)then
local Jhd,Khd=pcall(bb.liveDps,Hhd,Ihd)
Khd=Jhd and Khd or 0
local Lhd=V.types(Ihd)
Ehd=Ehd+Khd
if Lhd[Dhd]or Lhd[Dhd..qAe[2358]]then
Fhd=Fhd+Khd
end
end
end
local Mhd=0
for Nhd,Ohd in ipairs(bb.mine or{})do
if not V.isFarm(Ohd._stats.id.Value)then
Mhd=Mhd+1
end
end
local Phd=Mhd/(Mhd+4)
return Phd*(Ehd>0 and Fhd/Ehd or 0.5)+(1-Phd)*0.5
end
function bb.resistOf(Qhd)
local Rhd=V.types(Qhd)
local Shd=0
for Thd,Uhd in pairs(bb.fhResist or{})do
local Vhd=tostring(Thd):gsub(qAe[4004],qAe[1068])
if Rhd[Vhd]or Rhd[Vhd..qAe[2358]]then
Shd=math.max(Shd,Uhd/100)
end
end
return math.min(0.95,Shd)
end
function bb.rogueEffect(Whd)
local Xhd,Yhd,Zhd=Whd.type,tonumber(Whd.amount)or 0,tostring(Whd.stat or qAe[1068])
if Xhd==qAe[2700]then
return 1,math.abs(Yhd)
end
if Xhd==qAe[4128]or Xhd==qAe[4133]or Xhd==qAe[4129]then
if Zhd==qAe[2590]then
return math.max(0.3,1+Yhd),0
end
if Zhd==qAe[2407]then
return math.max(0.5,1+Yhd/2),0
end
if Zhd:find(qAe[2927])then
return 1/math.max(0.3,1+Yhd),0
end
return 1,0
end
if Xhd==qAe[4715]then
if Zhd==qAe[2590]then
return math.max(0.3,Yhd),0
end
if Zhd==qAe[2407]then
return math.max(0.5,1+(Yhd-1)/2),0
end
if Zhd:find(qAe[2927])then
return 1/math.max(0.3,Yhd),0
end
return 1,0
end
if Xhd==qAe[4135]then
return 1+Yhd/3,0
end
if Xhd==qAe[4141]then
return 1/math.max(0.3,1+Yhd),0
end
if Xhd==qAe[4716]then
return math.max(0.2,1-bb.rogueShare(Whd.damage_type)*(1-100/(100+Yhd))),0
end
if Xhd==qAe[4717]then
return 1+bb.rogueShare(Whd.damage_type)*Yhd,0
end
if Xhd==qAe[4718]then
return math.max(0.5,1-Yhd*0.5),0
end
if Xhd==qAe[4719]then
return math.max(0.5,1-Yhd*0.2),0
end
if Xhd==qAe[4720]then
return 1+Yhd*0.1,0
end
if Xhd==qAe[4721]then
return 1/math.max(0.3,1+Yhd*0.5),0
end
if Xhd==qAe[4722]then
return math.max(0.5,1-Yhd*0.1),0
end
if Xhd==qAe[4136]then
return 1/math.max(0.3,1+Yhd),0
end
if Xhd==qAe[4142]then
return math.max(0.3,1-Yhd*20),0
end
if Xhd==qAe[4143]then
return math.max(0.5,1-Yhd*0.03),0
end
if Xhd==qAe[4723]then
return 0.95,0
end
if Xhd==qAe[4144]then
return math.max(0.5,1-Yhd),0
end
if Xhd==qAe[4724]then
return 1+math.min(0.3,Yhd/40000),0
end
if Xhd==qAe[4137]then
return 1/math.max(0.3,1+Yhd/2),0
end
if Xhd==qAe[4725]then
return 0.8,0
end
if Xhd==qAe[4726]then
local _hd=math.max(1,math.abs(Yhd))*math.max(1,math.abs(tonumber(Whd.tier)or 1))
return Whd._type==qAe[4727]and 1.1^_hd or 0.8^_hd,0
end
return 1,0
end
function bb.effectText(aid)
return string.format(qAe[4728],tostring(aid.type),aid.stat and(qAe[2740]..tostring(aid.stat))or qAe[1068],tostring(aid.amount))
end
function bb.learn()
local cid=bb.calRun and bb.calRun.potBy
if type(cid)~=qAe[2149]then
return
end
pcall(bb.sampleHelpers,true)
local did={}
for eid,fid in pairs(bb.ownDealt or{})do
if not V.isFarm(fid.id)then
did[fid.id]=(did[fid.id]or 0)+(tonumber(fid.v)or 0)
end
end
for gid,hid in pairs(bb.helperDealt or{})do
if hid.owner and V.SUMMONER[hid.owner]and not V.droneHelper(hid)then
did[hid.owner]=(did[hid.owner]or 0)+(tonumber(hid.v)or 0)
end
end
local iid=type(bb.calRun.potExp)==qAe[2149]and bb.calRun.potExp or{}
local jid,kid=0,0
local lid={}
for nid,oid in pairs(cid)do
if oid>0 then
jid,kid=jid+(did[nid]or 0),kid+oid
local qid=tonumber(iid[nid])or oid
if qid>0 then
table.insert(lid,{id=nid,r=(did[nid]or 0)/qid,w=qid})
end
end
end
if jid<=0 or kid<=0 then
return
end
table.sort(lid,function(rid,sid)
return rid.r<sid.r
end)
local function tid(vid)
local wid,xid=0,0
for yid,zid in ipairs(lid)do
if zid.id~=vid then
wid=wid+zid.w
end
end
if wid<=0 then
return nil
end
for Aid,Bid in ipairs(lid)do
if Bid.id~=vid then
xid=xid+Bid.w
if xid>=wid/2 then
return Bid.r
end
end
end
end
bb.lastEff={}
for Cid,Did in pairs(cid)do
local Eid=tid(Cid)
if Did>0 and Did/kid>0.02 and Eid and Eid>0 then
local Fid=P.learn[Cid]or{eff=1,n=0,v=6}
V.learnUp(Cid,Fid)
local Gid=math.max(0.02,0.25*math.sqrt(30/(30+Fid.n)))
local Hid=U.clamp(((did[Cid]or 0)/Did)/Eid,0.2,6)
bb.lastEff[Cid]=math.floor(Hid*1000+0.5)/1000
Fid.eff=Fid.eff+(Hid-Fid.eff)*Gid
Fid.n=Fid.n+1
P.learn[Cid]=Fid
end
end
local Iid=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Iid and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==qAe[2149]and P.mapLearn or{}
local Jid=type(P.mapLearn[Iid])==qAe[2149]and P.mapLearn[Iid]or{}
for Kid,Lid in pairs(bb.lastEff)do
local Mid=type(Jid[Kid])==qAe[2149]and Jid[Kid]or{eff=Lid,n=0,v=6}
if(tonumber(Mid.v)or 0)<4 then
Mid.eff,Mid.v=(tonumber(Mid.eff)or Lid)*V.secRescale(Kid),4
end
if(tonumber(Mid.v)or 0)<5 then
Mid.eff,Mid.v=(tonumber(Mid.eff)or Lid)*(V.sumRescale(Kid)or 1),5
end
if(tonumber(Mid.v)or 0)<6 then
Mid.eff,Mid.v=(tonumber(Mid.eff)or Lid)*(1-(V.SUMMONER[Kid]and V.SUMMONER[Kid].droneShare or 0)),6
end
local Nid=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Mid.n)or 0))))
Mid.eff=(tonumber(Mid.n)or 0)==0 and Lid or((tonumber(Mid.eff)or Lid)+(Lid-(tonumber(Mid.eff)or Lid))*Nid)
Mid.n=(tonumber(Mid.n)or 0)+1
Jid[Kid]=Mid
end
Jid._at=os.time()
P.mapLearn[Iid]=Jid
if U.count(P.mapLearn)>80 then
local Oid,Pid
for Qid,Rid in pairs(P.mapLearn)do
if not Pid or(tonumber(Rid._at)or 0)<Pid then
Oid,Pid=Qid,tonumber(Rid._at)or 0
end
end
P.mapLearn[Oid]=nil
end
end
end
function bb.randomTeam()
