local Tid=Sid and Sid.collection.temporary_units or{}
local Uid,Vid={},{}
local function Wid(Xid,Yid,Zid)
local ajd=Xid and Tid[Xid]
if ajd and N.Units[ajd.unit_id]and not Vid[Xid]then
Vid[Xid]=true
table.insert(Uid,{slot=Zid or 99,uuid=Xid,u=ajd,id=ajd.unit_id,data=N.Units[ajd.unit_id],hand=Yid})
end
end
for bjd,cjd in pairs(Sid and Sid.override_equipped_units or{})do
Wid(cjd,true,tonumber(bjd))
