function bb.fhSnap()
local ijd,jjd=nil,nil
pcall(function()
for kjd,ljd in ipairs(workspace._BASES:GetDescendants())do
if ljd:IsA(qAe[2549])then
ijd,jjd=ljd.Health,ljd.MaxHealth
break
end
end
end)
local mjd=ijd and jjd and jjd>0 and math.floor(ijd/jjd*100)or-1
local njd,ojd,pjd=0,{},{}
for qjd,rjd in ipairs(bb.enemies or{})do
if(rjd.prog or 0)>0.8 then
njd=njd+1
ojd[tostring(rjd.m)]=(ojd[tostring(rjd.m)]or 0)+1
end
pjd[tostring(rjd.m)]=(pjd[tostring(rjd.m)]or 0)+1
end
