table.insert(bb.fhWaves,string.format(qAe[4729],bb.wave(),mjd,#(bb.enemies or{}),njd,U.fmt(sjd),bb.fieldCount(),bb.fhMult or 1,U.fmt(bb.money()),math.floor(bb.airShare()*100+0.5),xjd))
if mjd>=0 and bb.fhLastPct and mjd<bb.fhLastPct and not bb.fhLeak then
local Ajd={}
for Bjd,Cjd in pairs(ojd)do
table.insert(Ajd,V.name(Bjd)..qAe[4730]..Cjd)
end
bb.fhLeak=string.format(qAe[4731],bb.wave(),bb.fhLastPct,mjd,#Ajd>0 and table.concat(Ajd,qAe[2268])or qAe[4198])
