function bb.fhRecord(Djd,Ejd)
local Fjd,Gjd={},0
for Hjd,Ijd in ipairs(bb.mine or{})do
local Jjd=Ijd._stats
local Kjd=Jjd:FindFirstChild(qAe[2533])and tonumber(Jjd.total_damage.Value)or 0
local Ljd=Jjd.id.Value
if Kjd>0 then
Fjd[Ljd]=(Fjd[Ljd]or 0)+Kjd
Gjd=Gjd+Kjd
