local Qjd=P.fh.units[Njd]or{n=0,share=0}
Qjd.share=(Qjd.share*Qjd.n+Pjd)/(Qjd.n+1)
Qjd.n=Qjd.n+1
P.fh.units[Njd]=Qjd
