table.insert(P.fh.runs,1,{at=os.time(),wave=bb.wave(),won=Ejd or nil,coins=Djd,top=Tjd,mult=bb.fhMult or 1,discards=bb.discards,strength=bb.fhP,floor=Vjd,effects=bb.fhEffects,picks=bb.fhPicks,leak=bb.fhLeak,waves=bb.fhWaves})
while#P.fh.runs>20 do
