function bb.baseVerdict(Bod,Cod)
local Dod=(Cod.t or 0)-(Bod.t or 0)
if Dod<bb.BASE_WIN-1 then
return false
end
local Eod=((tonumber(Bod.base)or 0)-(tonumber(Cod.base)or 0))/Dod
if Eod<=0 or(tonumber(Cod.base)or 0)<=0 then
return false
end
local Fod=Cod.base/Eod
local God,Hod=0,0
local Iod,Jod=Bod.foes or{},Cod.foes or{}
for Kod,Lod in pairs(Jod)do
if Lod.prog>=bb.BASE_END then
God=God+Lod.hp
local Mod=Iod[Kod]
if Mod then
Hod=Hod+math.max(0,Mod.hp-Lod.hp)
end
end
end
for Nod,Ood in pairs(Iod)do
if Ood.prog>=bb.BASE_END and not Jod[Nod]then
Hod=Hod+Ood.hp
end
end
if God<=0 then
return false
end
local Pod=Hod/Dod
local Qod=Pod>0 and God/Pod or math.huge
local Rod={baseTime=Fod,loss=Eod,atEnd=God,rate=Pod,killTime=Qod}
return Fod<bb.BASE_SOON and Qod>Fod*bb.BASE_MARGIN,Rod
end
